'use client'

import { data as dataDE } from '@/data'
import ChapterRenderer from '@/components/progress/ChapterRenderer'
import { Data } from '@/types'

export default async function ChapterPage(props: {
  params: Promise<{ chapterId: string }>
}) {
  const params = await props.params
  const { chapterId } = params

  const data = JSON.parse(
    localStorage.getItem('data') || JSON.stringify(dataDE),
  ) as Data

  const chapter = data.chapters[parseInt(chapterId, 10)]

  return (
    <ChapterRenderer
      chapterId={chapter.id ?? chapterId}
      components={chapter.components}
    />
  )
}
